import type { Quat, Vec3 } from '../contracts/math';
import type {
  HazardObstacle,
  MovingObstacle,
  ObstacleDescriptor,
  StaticObstacle,
  TransformDescriptor,
} from '../courses/types';
import type { ObstaclePose } from './types';

export const IDENTITY_ROTATION: Quat = { x: 0, y: 0, z: 0, w: 1 };
export const UNIT_SCALE: Vec3 = { x: 1, y: 1, z: 1 };

/** Rapier rejects degenerate colliders, so every half extent keeps a floor. */
const MIN_HALF_EXTENT = 1e-3;

export function isMovingObstacle(descriptor: ObstacleDescriptor): descriptor is MovingObstacle {
  return (
    descriptor.type === 'spinner' ||
    descriptor.type === 'windmill' ||
    descriptor.type === 'gate' ||
    descriptor.type === 'platform'
  );
}

export function isHazardObstacle(descriptor: ObstacleDescriptor): descriptor is HazardObstacle {
  return descriptor.type === 'water' || descriptor.type === 'void' || descriptor.type === 'reset-zone';
}

export function isStaticObstacle(descriptor: ObstacleDescriptor): descriptor is StaticObstacle {
  return !isMovingObstacle(descriptor) && !isHazardObstacle(descriptor);
}

export function clonePose(pose: ObstaclePose): ObstaclePose {
  return { position: { ...pose.position }, rotation: { ...pose.rotation } };
}

/** Authored placement of an obstacle before any motion is applied. */
export function basePoseOf(transform: TransformDescriptor): ObstaclePose {
  return {
    position: { ...transform.position },
    rotation: transform.rotation ? { ...transform.rotation } : { ...IDENTITY_ROTATION },
  };
}

export function obstacleScale(transform: TransformDescriptor): Vec3 {
  return transform.scale ? { ...transform.scale } : { ...UNIT_SCALE };
}

/** Collider half extents: authored size scaled by the transform scale. */
export function halfExtents(descriptor: ObstacleDescriptor): Vec3 {
  const scale = obstacleScale(descriptor.transform);
  const size = descriptor.size;
  return {
    x: Math.max(Math.abs(size.x * scale.x) / 2, MIN_HALF_EXTENT),
    y: Math.max(Math.abs(size.y * scale.y) / 2, MIN_HALF_EXTENT),
    z: Math.max(Math.abs(size.z * scale.z) / 2, MIN_HALF_EXTENT),
  };
}
